    payload = {
        "name": scenario_case.get("name"),
        "photoUrls": scenario_case.get("photoUrls")
    }
    if "category" in scenario_case:
        payload["category"] = scenario_case["category"]
    if "tags" in scenario_case:
        payload["tags"] = scenario_case["tags"]
    if "status" in scenario_case:
        payload["status"] = scenario_case["status"]

    # Define headers for request
    headers = {
        "Authorization": f"Bearer {petstore_auth}",
        "Content-Type": "application/json"
    }

    # Make the request
    response = api_client.post("/pet", headers=headers, data=json.dumps(payload))
    
    # Validate the response status code
